import sys

def main():
    data = sys.stdin.read().strip()
    if not data:
        return
    R = int(data)

    for i in range(1, R + 1):
        chars = []
        for j in range(2 * i - 1):
            chars.append(chr(ord('A') + j))
        print(''.join(chars))

if __name__ == "__main__":
    main()
